-- ====================================================================================================
-- Smart ATS (CVision) - CẤU TRÚC DATABASE PostgreSQL
-- Sinh tự động từ migration Django: khớp 100% với code backend hiện tại. Không sửa tay.
-- Gồm: bảng / ràng buộc / index, lịch sử migration (để `manage.py migrate` không tạo lại bảng)
--      và danh mục bắt buộc (tỉnh/thành, ngành nghề, kỹ năng).
--
-- Cách dùng (database phải TRỐNG):
--   CREATE DATABASE "CVision";        -- giữ dấu nháy kép vì tên có chữ hoa
--   psql -U postgres -d CVision -v ON_ERROR_STOP=1 -f database/schema.sql
--   psql -U postgres -d CVision -v ON_ERROR_STOP=1 -f database/seed.sql      (dữ liệu mẫu, tùy chọn)
-- PostgreSQL 13 trở lên.
-- ====================================================================================================

SET client_encoding = 'UTF8';
BEGIN;

-- ====================================================================================================
-- 1. BẢNG, RÀNG BUỘC, INDEX (26 bảng)
-- ====================================================================================================


-- users
CREATE TABLE "users" ("password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "id" uuid NOT NULL PRIMARY KEY, "email" varchar(254) NOT NULL UNIQUE, "full_name" varchar(150) NOT NULL, "phone" varchar(20) NOT NULL, "role" varchar(20) NOT NULL, "is_active" boolean NOT NULL, "is_staff" boolean NOT NULL, "email_verified_at" timestamp with time zone NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "deleted_at" timestamp with time zone NULL, CONSTRAINT "ck_users_role" CHECK ("role" IN ('candidate', 'employer', 'admin')));

-- users_groups
CREATE TABLE "users_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" uuid NOT NULL, "group_id" integer NOT NULL);

-- users_user_permissions
CREATE TABLE "users_user_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" uuid NOT NULL, "permission_id" integer NOT NULL);

-- django_admin_log
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "action_time" timestamp with time zone NOT NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL, "user_id" uuid NOT NULL);

-- applications
CREATE TABLE "applications" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "cover_letter" text NOT NULL, "status" varchar(20) NOT NULL, "rejection_reason" text NOT NULL, "recruiter_rating" smallint NULL CHECK ("recruiter_rating" >= 0), "status_changed_at" timestamp with time zone NOT NULL, "candidate_id" uuid NOT NULL, "cv_id" uuid NOT NULL, "job_id" uuid NOT NULL, CONSTRAINT "uq_applications_job_candidate" UNIQUE ("job_id", "candidate_id"), CONSTRAINT "ck_applications_status" CHECK ("status" IN ('applied', 'screening', 'interview', 'offer', 'hired', 'rejected', 'withdrawn')), CONSTRAINT "ck_applications_rating_range" CHECK (("recruiter_rating" IS NULL OR ("recruiter_rating" >= 1 AND "recruiter_rating" <= 5))));

-- application_status_history
CREATE TABLE "application_status_history" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "from_status" varchar(20) NULL, "to_status" varchar(20) NOT NULL, "note" text NOT NULL, "created_at" timestamp with time zone NOT NULL, "application_id" uuid NOT NULL, "changed_by_id" uuid NULL);

-- auth_permission
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" varchar(100) NOT NULL);

-- auth_group
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);

-- auth_group_permissions
CREATE TABLE "auth_group_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL);

-- candidate_profiles
CREATE TABLE "candidate_profiles" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "headline" varchar(200) NOT NULL, "date_of_birth" date NULL, "gender" varchar(10) NOT NULL, "address" varchar(255) NOT NULL, "summary" text NOT NULL, "years_of_experience" numeric(4, 1) NULL, "current_level" varchar(20) NOT NULL, "desired_position" varchar(150) NOT NULL, "desired_salary_min" bigint NULL, "desired_salary_max" bigint NULL, "salary_currency" varchar(3) NOT NULL, "desired_job_type" varchar(20) NOT NULL, "desired_work_mode" varchar(20) NOT NULL, "is_open_to_work" boolean NOT NULL, "is_public" boolean NOT NULL, "location_id" bigint NULL, "user_id" uuid NOT NULL UNIQUE, CONSTRAINT "ck_candidate_years_non_negative" CHECK ("years_of_experience" >= 0), CONSTRAINT "ck_candidate_desired_salary_range" CHECK (("desired_salary_max" IS NULL OR "desired_salary_min" IS NULL OR "desired_salary_max" >= ("desired_salary_min"))));

-- locations
CREATE TABLE "locations" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL, "slug" varchar(170) NOT NULL UNIQUE, "country_code" varchar(2) NOT NULL);

-- industries
CREATE TABLE "industries" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL, "slug" varchar(170) NOT NULL UNIQUE, "parent_id" bigint NULL);

-- skills
CREATE TABLE "skills" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(100) NOT NULL, "slug" varchar(120) NOT NULL UNIQUE, "category" varchar(20) NOT NULL, "aliases" jsonb NOT NULL, "is_verified" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, CONSTRAINT "ck_skills_category" CHECK ("category" IN ('technical', 'soft', 'language', 'tool', 'domain')));

-- django_content_type
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);

-- cvs
CREATE TABLE "cvs" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "deleted_at" timestamp with time zone NULL, "title" varchar(150) NOT NULL, "file" varchar(500) NOT NULL, "original_filename" varchar(255) NOT NULL, "mime_type" varchar(100) NOT NULL, "file_size" integer NOT NULL CHECK ("file_size" >= 0), "file_hash" varchar(64) NOT NULL, "language" varchar(10) NOT NULL, "is_default" boolean NOT NULL, "candidate_id" uuid NOT NULL, "parse_status" varchar(20) NOT NULL, "parse_error" text NOT NULL, "raw_text" text NOT NULL, "parsed_data" jsonb NULL, "parsed_at" timestamp with time zone NULL, CONSTRAINT "ck_cvs_mime_type" CHECK ("mime_type" IN ('application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')), CONSTRAINT "ck_cvs_file_size_positive" CHECK ("file_size" > 0), CONSTRAINT "ck_cvs_parse_status" CHECK ("parse_status" IN ('pending', 'processing', 'completed', 'failed')));

-- companies
CREATE TABLE "companies" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "deleted_at" timestamp with time zone NULL, "name" varchar(255) NOT NULL, "slug" varchar(280) NOT NULL UNIQUE, "tax_code" varchar(20) NULL UNIQUE, "logo" varchar(500) NOT NULL, "website" varchar(255) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "address" varchar(255) NOT NULL, "company_size" varchar(20) NOT NULL, "founded_year" smallint NULL CHECK ("founded_year" >= 0), "description" text NOT NULL, "verification_status" varchar(20) NOT NULL, "verified_at" timestamp with time zone NULL, "created_by_id" uuid NULL, "industry_id" bigint NULL, "location_id" bigint NULL, "verified_by_id" uuid NULL, CONSTRAINT "ck_companies_verification_status" CHECK ("verification_status" IN ('pending', 'verified', 'rejected')));

-- recruiters
CREATE TABLE "recruiters" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "position" varchar(100) NOT NULL, "company_role" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "joined_at" timestamp with time zone NULL, "company_id" uuid NOT NULL, "user_id" uuid NOT NULL UNIQUE, CONSTRAINT "ck_recruiters_company_role" CHECK ("company_role" IN ('owner', 'admin', 'member')), CONSTRAINT "ck_recruiters_status" CHECK ("status" IN ('pending', 'active', 'removed')));

-- favorite_companies
CREATE TABLE "favorite_companies" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamp with time zone NOT NULL, "candidate_id" uuid NOT NULL, "company_id" uuid NOT NULL, CONSTRAINT "uq_favorite_companies_candidate_company" UNIQUE ("candidate_id", "company_id"));

-- favorite_jobs
CREATE TABLE "favorite_jobs" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamp with time zone NOT NULL, "candidate_id" uuid NOT NULL, "job_id" uuid NOT NULL, CONSTRAINT "uq_favorite_jobs_candidate_job" UNIQUE ("candidate_id", "job_id"));

-- jobs
CREATE TABLE "jobs" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "deleted_at" timestamp with time zone NULL, "title" varchar(255) NOT NULL, "slug" varchar(300) NOT NULL UNIQUE, "description" text NOT NULL, "requirements" text NOT NULL, "benefits" text NOT NULL, "job_type" varchar(20) NOT NULL, "work_mode" varchar(20) NOT NULL, "level" varchar(20) NOT NULL, "min_years_experience" numeric(4, 1) NOT NULL, "salary_min" bigint NULL, "salary_max" bigint NULL, "salary_currency" varchar(3) NOT NULL, "is_salary_negotiable" boolean NOT NULL, "headcount" smallint NOT NULL CHECK ("headcount" >= 0), "address" varchar(255) NOT NULL, "deadline" date NULL, "status" varchar(20) NOT NULL, "published_at" timestamp with time zone NULL, "closed_at" timestamp with time zone NULL, "view_count" integer NOT NULL CHECK ("view_count" >= 0), "application_count" integer NOT NULL CHECK ("application_count" >= 0), "company_id" uuid NOT NULL, "created_by_id" uuid NULL, "industry_id" bigint NULL, "location_id" bigint NULL, CONSTRAINT "ck_jobs_status" CHECK ("status" IN ('draft', 'published', 'paused', 'closed', 'expired')), CONSTRAINT "ck_jobs_job_type" CHECK ("job_type" IN ('full_time', 'part_time', 'internship', 'contract', 'freelance')), CONSTRAINT "ck_jobs_work_mode" CHECK ("work_mode" IN ('onsite', 'remote', 'hybrid')), CONSTRAINT "ck_jobs_salary_min_non_negative" CHECK ("salary_min" >= 0), CONSTRAINT "ck_jobs_salary_range" CHECK (("salary_max" IS NULL OR "salary_min" IS NULL OR "salary_max" >= ("salary_min"))), CONSTRAINT "ck_jobs_headcount_positive" CHECK ("headcount" > 0), CONSTRAINT "ck_jobs_min_years_non_negative" CHECK ("min_years_experience" >= 0), CONSTRAINT "ck_jobs_level" CHECK ("level" IN ('intern', 'fresher', 'staff', 'supervisor', 'manager', 'director')));

-- job_skills
CREATE TABLE "job_skills" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "is_required" boolean NOT NULL, "min_years" numeric(4, 1) NULL, "weight" smallint NOT NULL CHECK ("weight" >= 0), "job_id" uuid NOT NULL, "skill_id" bigint NOT NULL, CONSTRAINT "uq_job_skills_job_skill" UNIQUE ("job_id", "skill_id"), CONSTRAINT "ck_job_skills_weight_range" CHECK (("weight" >= 1 AND "weight" <= 5)));

-- django_session
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" timestamp with time zone NOT NULL);

-- token_blacklist_blacklistedtoken
CREATE TABLE "token_blacklist_blacklistedtoken" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "blacklisted_at" timestamp with time zone NOT NULL, "token_id" bigint NOT NULL UNIQUE);

-- token_blacklist_outstandingtoken
CREATE TABLE "token_blacklist_outstandingtoken" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "token" text NOT NULL, "created_at" timestamp with time zone NULL, "expires_at" timestamp with time zone NOT NULL, "user_id" uuid NULL, "jti" varchar(255) NOT NULL UNIQUE);

-- invitations
CREATE TABLE "invitations" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "message" text NOT NULL, "status" varchar(20) NOT NULL, "read_at" timestamp with time zone NULL, "responded_at" timestamp with time zone NULL, "application_id" uuid NULL, "candidate_id" uuid NOT NULL, "job_id" uuid NOT NULL, "sender_id" uuid NULL, CONSTRAINT "uq_invitations_job_candidate" UNIQUE ("job_id", "candidate_id"), CONSTRAINT "ck_invitations_status" CHECK ("status" IN ('pending', 'accepted', 'declined')));
